  const A = key => local(copy[key]);
  const auth=window.PersiaAuth;
  let user=auth.user, authMode="login", authMessage="", authBusy=false;
  const api=async(path,options)=>{try{return await auth.request(path,options);}catch(error){if(['sessionExpired','accountChanged'].includes(error.code)&&auth.user){location.reload();}throw error;}};
  const errorText=error=>A(copy[error.code]?error.code:"serverError");
  const e = escapeHtml;
  const panel = document.querySelector('#account-panel');
  const text = (value,max=120) => typeof value === 'string' ? value.trim().slice(0,max) : '';
  const rawProfile = user||{};
  let profile = {name:text(rawProfile?.name,80),email:text(rawProfile?.email,160),phone:text(rawProfile?.phone,40)};
  const validAddress = a => a && typeof a.id === 'string' && /^[a-zA-Z0-9-]{1,40}$/.test(a.id) && typeof a.label === 'string' && a.label.length>0 && a.label.length<=40 && typeof a.recipient==='string' && a.recipient.length<=80 && typeof a.street==='string' && a.street.length>0 && a.street.length<=160 && typeof a.city==='string' && a.city.trim().length>=2 && a.city.length<=80 && /^[0-9]{5}$/.test(a.postcode);
  let addressData={addresses:[],defaultId:''};
  if(user){try{addressData=await api('/api/account/addresses');}catch(error){authMessage=errorText(error);}}
  const rawAddresses=addressData.addresses;
  let addresses=Array.isArray(rawAddresses) ? rawAddresses.filter(validAddress).filter((a,i,list)=>list.findIndex(x=>x.id===a.id)===i).slice(0,20) : [];
  let defaultId=addressData.defaultId;
  if(!addresses.some(a=>a.id===defaultId))defaultId=addresses[0]?.id||'';
  let tab='overview', editing=null, addressForm=false, removed=null, message='';
  const saveAddresses=async(list,defaultAddress)=>{
    try {const data=await api('/api/account/addresses',{method:'PUT',body:{addresses:list,defaultId:defaultAddress}});addresses=data.addresses;defaultId=data.defaultId;return true;}catch(error){message=errorText(error);return false;}
  };
  const button=(label,attr='',primary=false)=>'<button type="button" class="button '+(primary?'primary':'account-outline')+'" '+attr+'>'+e(label)+'</button>';
  const go=(target,label)=>button(label,'data-account-tab="'+target+'"');
  const field=(id,label,value,attrs='')=>'<label for="'+id+'"><span>'+e(label)+'</span><input id="'+id+'" name="'+id+'" value="'+e(value)+'" '+attrs+'></label>';
  const empty=(body)=>'<div class="account-empty"><span aria-hidden="true">✧</span><p>'+e(body)+'</p>'+button(A('start'),'data-account-shop data-category="hani"',true)+'</div>';
  function orderList(list) {
    return list.length ? '<div class="account-orders">'+list.map(order=>'<article class="account-order"><div class="account-order-top"><b dir="ltr">'+e(order.id)+'</b><span class="account-badge">'+e(A('demoStatus'))+'</span></div><p class="muted">'+e(new Intl.DateTimeFormat(lang==='fa'?'fa-IR':lang==='it'?'it-IT':'en-GB',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(order.date)))+' · '+e(order.destination.city)+' · <span dir="ltr">'+e(order.destination.postcode)+'</span></p><p>'+order.lines.map(line=>e(orderLineName(line))+' × '+number(line.quantity)).join(' · ')+'</p><div class="account-order-bottom"><strong>'+money(total(order.lines))+'</strong><div>'+button(A('receipt'),'data-receipt="'+order.id+'"')+button(A('repeat'),'data-repeat-order="'+order.id+'"')+'</div></div></article>').join('')+'</div>' : empty(A('noOrders'));
  }
  function overview() {
    const defaultAddress=addresses.find(a=>a.id===defaultId);
    return '<div class="account-stats">'+[['orders',orderHistory.length,A('orders')],['saved',favorites.size,A('saved')],['addresses',addresses.length,A('addresses')]].map(([target,count,label])=>'<button class="account-stat" data-account-tab="'+target+'"><span>'+e(label)+'</span><strong>'+number(count)+'</strong><small>'+e(A('seeAll'))+' →</small></button>').join('')+'</div><div class="account-duo"><article class="account-card"><p class="eyebrow">'+e(A('profile'))+'</p><h3>'+e(profile.name||A('emptyName'))+'</h3><p class="muted">'+e(profile.email||A('profileHint'))+'</p><p dir="ltr">'+e(profile.phone)+'</p>'+go('profile',A('editProfile'))+'</article><article class="account-card"><p class="eyebrow">'+e(A('default'))+'</p><h3>'+e(defaultAddress?.label||A('addresses'))+'</h3><p class="muted">'+e(defaultAddress ? defaultAddress.city+' · '+defaultAddress.postcode:A('noAddresses'))+'</p>'+go('addresses',A('addAddress'))+'</article></div><div class="account-section-title"><h2>'+e(A('recent'))+'</h2>'+go('orders',A('seeAll'))+'</div>'+orderList(orderHistory.slice(0,2));
  }
  function profileView() {
    return '<article class="account-card"><h2>'+e(A('profile'))+'</h2><p class="muted">'+e(A('profileHint'))+'</p><form id="account-profile-form" class="account-form"><div class="account-fields">'+field('profile-name',A('name'),profile.name,'required minlength="2" maxlength="80" autocomplete="name"')+field('profile-email',A('email'),profile.email,'type="email" readonly dir="ltr"')+field('profile-phone',A('phone'),profile.phone,'type="tel" maxlength="40" autocomplete="tel" dir="ltr" aria-describedby="profile-phone-hint"')+'<label for="profile-language"><span>'+e(A('language'))+'</span><select id="profile-language">'+[['fa','فارسی'],['it','Italiano'],['en','English']].map(([code,label])=>'<option value="'+code+'" '+(lang===code?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div><p id="profile-phone-hint" class="muted">'+e(A('phoneHint'))+'</p><button class="button primary" type="submit">'+e(A('save'))+'</button></form></article>';
  }
  function addressesView() {
    const address=addresses.find(a=>a.id===editing)||{};
    const form=addressForm ? '<article class="account-card address-editor"><h3>'+e(A(editing?'editAddress':'addAddress'))+'</h3><form id="account-address-form" class="account-form"><div class="account-fields">'+field('address-label',A('addressLabel'),address.label||'','required maxlength="40" autocomplete="off"')+field('address-recipient',A('recipient'),address.recipient||'','maxlength="80" autocomplete="off"')+field('address-street',A('street'),address.street||'','required maxlength="160" autocomplete="off"')+field('address-city',A('city'),address.city||'','required minlength="2" maxlength="80" autocomplete="off"')+field('address-postcode',A('postcode'),address.postcode||'','required pattern="[0-9]{5}" maxlength="5" inputmode="numeric" dir="ltr" autocomplete="off"')+'<div class="account-country"><span>'+e(t('country'))+'</span><b>'+e(A('country'))+'</b></div></div><label class="account-check"><input id="address-default" type="checkbox" '+(defaultId===editing||!addresses.length?'checked':'')+'><span>'+e(A('makeDefault'))+'</span></label><div class="account-actions"><button class="button primary" type="submit">'+e(A('save'))+'</button>'+button(A('cancel'),'data-cancel-address')+'</div></form></article>' : '';
    return '<div class="account-section-title"><h2>'+e(A('addresses'))+'</h2>'+(!addressForm?button(A('addAddress'),'data-new-address',true):'')+'</div><p class="muted">'+e(A('addressNote'))+'</p>'+form+(removed?'<div class="account-undo" role="status">'+e(A('removed'))+' '+button(A('undo'),'data-undo-address')+'</div>':'')+'<div class="account-address-grid">'+addresses.map(a=>'<article class="account-card"><div class="account-section-title"><h3>'+e(a.label)+'</h3>'+(a.id===defaultId?'<span class="account-badge">'+e(A('default'))+'</span>':'')+'</div><p>'+e(a.recipient)+'</p><p>'+e(a.street)+'</p><p>'+e(a.city)+' · <span dir="ltr">'+e(a.postcode)+'</span> · '+e(A('country'))+'</p><div class="account-actions">'+button(A('edit'),'data-edit-address="'+a.id+'"')+button(A('remove'),'data-remove-address="'+a.id+'"')+(a.id!==defaultId?button(A('makeDefault'),'data-default-address="'+a.id+'"'):'')+'</div></article>').join('')+'</div>'+(!addresses.length&&!addressForm?empty(A('noAddresses')):'');
  }
